-- PT112-S1-Q13. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT112-S1-Q13$batch03$ AND q.stimulus=$batch03$When astronomers observed the comet Schwassman-Wachmann 3 becoming 1,000 times brighter in September 1995, they correctly hypothesized that its increased brightness was a result of the comet’s breaking up—when comets break up, they emit large amounts of gas and dust, becoming visibly brighter as a result. However, their observations did not reveal comet Schwassman-Wachmann 3 actually breaking into pieces until November 1995, even though telescopes were trained on it throughout the entire period.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent conflict in the statements above?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT112-S1-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT112-S1-Q13$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S1-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT112-S1-Q13$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$The comet brightened in September because it was breaking up, since breaking up releases bright gas and dust.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Astronomers watching all along did not see it break into pieces until November?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$"Breaking up" and "breaking into pieces" may not be the same moment. If a comet can crack and leak gas before it actually splits apart, the brightening and the visible split can be two months apart.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a way gas and dust could be released before the comet split into pieces.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT112-S1-Q13$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$If gas and dust come weeks *after* breakup begins, the comet should have split before it brightened. That runs the timeline the wrong way.$batch03$), ($batch03$B$batch03$, $batch03$Why gas and dust brighten a comet does not explain the gap between brightening and the visible split.$batch03$), ($batch03$C$batch03$, $batch03$Cracks can release gas and dust without the comet breaking all the way through. The comet began cracking in September, brightened, and split into pieces in November.$batch03$), ($batch03$D$batch03$, $batch03$A steady increase in gas and dust does not say why the pieces were not visible until November.$batch03$), ($batch03$E$batch03$, $batch03$This explains why the comet broke up. It does not explain the delay between the brightening and the visible split.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT112-S1-Q13$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
